  .loop-logo { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--text-on-primary); background: var(--grad-loop); box-shadow: var(--shadow-loop); font: 900 15px/1 'Segoe UI',system-ui,Pretendard,sans-serif; }
  .loop-search { display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 10px; border: 1px solid var(--border-default); border-radius: var(--radius-md); color: var(--text-tertiary); background: var(--bg-subtle); font: 500 12px/1 'Segoe UI',system-ui,Pretendard,sans-serif; }
  .loop-sidebar-label { margin: 18px 9px 7px; color: var(--text-tertiary); font: 700 10px/1 'Segoe UI',system-ui,Pretendard,sans-serif; text-transform: uppercase; letter-spacing: .08em; }
  .loop-workspace { display: flex; align-items: center; gap: 9px; padding: 8px; border-radius: var(--radius-md); font: 650 13px/1.2 'Segoe UI',system-ui,Pretendard,sans-serif; }
